INSERT INTO odyssey_daily_activities (slug, title, question, type, options, correct_answer, explanation, xp_reward, active) VALUES
('task-day-1', 'Keluarga: Waktu Berkualitas', 'Mana yang merupakan contoh waktu berkualitas bersama keluarga?', 'MCQ', '["Makan malam bersama tanpa HP","Menonton TV masing-masing","Bermain game sendiri di kamar","Pergi ke mall tapi pisah"]', 'Makan malam bersama tanpa HP', 'Waktu berkualitas membutuhkan interaksi penuh tanpa gangguan.', 10, true),
('task-day-2', 'Finansial: Tabungan', 'Mengapa penting menyisihkan uang untuk ditabung di awal bulan?', 'MCQ', '["Agar uang cepat habis","Agar tidak terpakai untuk keinginan sesaat","Untuk pamer ke teman","Tidak ada gunanya"]', 'Agar tidak terpakai untuk keinginan sesaat', 'Menabung di awal mencegah uang habis untuk kebutuhan tidak penting.', 10, true),
('task-day-3', 'Digital: Password', 'Password yang kuat sebaiknya mengandung huruf besar, huruf kecil, angka, dan simbol.', 'TRUE_FALSE', '["Benar","Salah"]', 'Benar', 'Kombinasi tersebut membuat password jauh lebih sulit ditebak.', 10, true),
('task-day-4', 'Karier: Etika Email', 'Saat mengirim email profesional, kolom Subject/Judul boleh dikosongkan.', 'TRUE_FALSE', '["Benar","Salah"]', 'Salah', 'Subject sangat penting agar penerima tahu isi email sebelum membukanya.', 10, true),
('task-day-5', 'Keluarga: Komunikasi', 'Apa yang sebaiknya dilakukan saat anggota keluarga sedang berbicara serius?', 'MCQ', '["Menyela pembicaraan","Mendengarkan dengan penuh perhatian","Memeriksa handphone","Pergi begitu saja"]', 'Mendengarkan dengan penuh perhatian', 'Mendengarkan aktif adalah bentuk penghargaan dan kasih sayang.', 10, true),
('task-day-6', 'Finansial: Dana Darurat', 'Dana darurat sebaiknya digunakan untuk membeli HP seri terbaru.', 'TRUE_FALSE', '["Benar","Salah"]', 'Salah', 'Dana darurat hanya untuk kejadian tak terduga seperti sakit atau kehilangan pekerjaan.', 10, true),
('task-day-7', 'Digital: Hoax', 'Semua berita yang dikirim melalui grup WhatsApp pasti benar.', 'TRUE_FALSE', '["Benar","Salah"]', 'Salah', 'Selalu verifikasi informasi dari sumber terpercaya sebelum mempercayainya.', 10, true),
('task-day-8', 'Karier: Wawancara', 'Pakaian apa yang paling tepat untuk wawancara kerja kantoran?', 'MCQ', '["Kaos oblong dan celana pendek","Kemeja rapi dan celana bahan","Pakaian tidur","Pakaian olahraga"]', 'Kemeja rapi dan celana bahan', 'Berpakaian rapi menunjukkan profesionalisme dan rasa hormat.', 10, true),
('task-day-9', 'Produktivitas: Fokus', 'Teknik Pomodoro adalah cara mengatur waktu dengan bekerja 25 menit lalu istirahat 5 menit.', 'TRUE_FALSE', '["Benar","Salah"]', 'Benar', 'Teknik ini terbukti ampuh menjaga fokus dan mencegah kelelahan mental.', 10, true),
