('task-day-353', 'Digital: Password', 'Password yang kuat sebaiknya mengandung huruf besar, huruf kecil, angka, dan simbol.', 'TRUE_FALSE', '["Benar","Salah"]', 'Benar', 'Kombinasi tersebut membuat password jauh lebih sulit ditebak.', 10, true),
('task-day-354', 'Karier: Etika Email', 'Saat mengirim email profesional, kolom Subject/Judul boleh dikosongkan.', 'TRUE_FALSE', '["Benar","Salah"]', 'Salah', 'Subject sangat penting agar penerima tahu isi email sebelum membukanya.', 10, true),
('task-day-355', 'Keluarga: Komunikasi', 'Apa yang sebaiknya dilakukan saat anggota keluarga sedang berbicara serius?', 'MCQ', '["Menyela pembicaraan","Mendengarkan dengan penuh perhatian","Memeriksa handphone","Pergi begitu saja"]', 'Mendengarkan dengan penuh perhatian', 'Mendengarkan aktif adalah bentuk penghargaan dan kasih sayang.', 10, true),
('task-day-356', 'Finansial: Dana Darurat', 'Dana darurat sebaiknya digunakan untuk membeli HP seri terbaru.', 'TRUE_FALSE', '["Benar","Salah"]', 'Salah', 'Dana darurat hanya untuk kejadian tak terduga seperti sakit atau kehilangan pekerjaan.', 10, true),
('task-day-357', 'Digital: Hoax', 'Semua berita yang dikirim melalui grup WhatsApp pasti benar.', 'TRUE_FALSE', '["Benar","Salah"]', 'Salah', 'Selalu verifikasi informasi dari sumber terpercaya sebelum mempercayainya.', 10, true),
('task-day-358', 'Karier: Wawancara', 'Pakaian apa yang paling tepat untuk wawancara kerja kantoran?', 'MCQ', '["Kaos oblong dan celana pendek","Kemeja rapi dan celana bahan","Pakaian tidur","Pakaian olahraga"]', 'Kemeja rapi dan celana bahan', 'Berpakaian rapi menunjukkan profesionalisme dan rasa hormat.', 10, true),
('task-day-359', 'Produktivitas: Fokus', 'Teknik Pomodoro adalah cara mengatur waktu dengan bekerja 25 menit lalu istirahat 5 menit.', 'TRUE_FALSE', '["Benar","Salah"]', 'Benar', 'Teknik ini terbukti ampuh menjaga fokus dan mencegah kelelahan mental.', 10, true),
('task-day-360', 'Finansial: Cicilan', 'Total cicilan utang per bulan sebaiknya tidak melebihi berapa persen dari gaji?', 'MCQ', '["30%","50%","80%","100%"]', '30%', 'Pakar keuangan menyarankan rasio utang tidak melebihi 30% dari pemasukan.', 10, true),
